    private string _languageCode = string.Empty;

    public LocalizationService() : this("system") { }
    public LocalizationService(string language) => ApplyLanguage(language);

    public string LanguageCode => _languageCode;
    public bool IsEnglish => _languageCode == "en-US";
    public string this[string key] => Entries.TryGetValue(key, out var entry)
        ? IsEnglish ? entry.English : entry.Chinese
        : key;

    public string Format(string key, params object?[] arguments) =>
        string.Format(CultureInfo.GetCultureInfo(_languageCode), this[key], arguments);

    public event PropertyChangedEventHandler? PropertyChanged;
    public event EventHandler? LanguageChanged;

    public void ApplyLanguage(string language)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(language);
        var resolved = language.Trim().ToLowerInvariant() switch
        {
            "system" => CultureInfo.CurrentUICulture.Name.StartsWith("zh", StringComparison.OrdinalIgnoreCase)
                ? "zh-CN" : "en-US",
            "zh-cn" => "zh-CN",
            "en-us" => "en-US",
            _ => throw new ArgumentException("Unsupported language.", nameof(language))
        };
        if (_languageCode == resolved) return;
        _languageCode = resolved;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs("Item[]"));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(LanguageCode)));
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(IsEnglish)));
        LanguageChanged?.Invoke(this, EventArgs.Empty);
    }
}
